"use strict";(self.webpackChunkwww=self.webpackChunkwww||[]).push([[96323],{95783:(e,t,n)=>{n.r(t),n.d(t,{assets:()=>r,contentTitle:()=>s,default:()=>c,frontMatter:()=>a,metadata:()=>i,toc:()=>d});var h=n(31085),o=n(71184);const a={sidebar_position:18,slug:"/bible/Judges/Judges_18",title:"Judges 18",hide_table_of_contents:!0},s="Judges",i={id:"bible/Judges/Judges 18",title:"Judges 18",description:"Chapter 18",source:"@site/docs/bible/Judges/Judges 18.md",sourceDirName:"bible/Judges",slug:"/bible/Judges/Judges_18",permalink:"/bibleNotes/docs/bible/Judges/Judges_18",draft:!1,unlisted:!1,editUrl:"https://github.com/ozkey/bibleNotes/tree/main/packages/www/docs/bible/Judges/Judges 18.md",tags:[],version:"current",sidebarPosition:18,frontMatter:{sidebar_position:18,slug:"/bible/Judges/Judges_18",title:"Judges 18",hide_table_of_contents:!0},sidebar:"bibleSidebar",previous:{title:"Judges 17",permalink:"/bibleNotes/docs/bible/Judges/Judges_17"},next:{title:"Judges 19",permalink:"/bibleNotes/docs/bible/Judges/Judges_19"}},r={},d=[{value:"Chapter 18",id:"chapter-18",level:2}];function l(e){const t={admonition:"admonition",h1:"h1",h2:"h2",p:"p",...(0,o.R)(),...e.components},{BibleText:n}=t;return n||function(e,t){throw new Error("Expected "+(t?"component":"object")+" `"+e+"` to be defined: you likely forgot to import, pass, or provide it.")}("BibleText",!0),(0,h.jsxs)(h.Fragment,{children:[(0,h.jsx)(t.h1,{id:"judges",children:"Judges"}),"\n",(0,h.jsx)(t.h2,{id:"chapter-18",children:"Chapter 18"}),"\n",(0,h.jsx)(t.p,{children:"The expedition of the men of Dan against Lais:  in their way they rob Michas of his priest and his gods."}),"\n",(0,h.jsx)(n,{verse:1,children:"In those days there was no king in Israel, and the tribe of Dan sought them an inheritance to dwell in: for unto that day they had not received their lot among the other tribes."}),"\n",(0,h.jsx)(t.admonition,{type:"note",children:(0,h.jsx)(t.p,{children:"Note 1: Not received, etc...They had their portions assigned them, Jos. 19.40. But, through their own sloth, possessed as yet but a small part of it. See Judges 1.34."})}),"\n",(0,h.jsx)(n,{verse:2,children:"So the children of Dan sent five most valiant men, of their stock and family, from Saraa and Esthaol, to spy out the land, and to view it diligently: and they said to them: Go, and view the land. They went on their way, and when they came to mount Ephraim, they went into the house of Michas, and rested there:"}),"\n",(0,h.jsx)(n,{verse:3,children:"And knowing the voice of the young man the Levite, and lodging with him, they said to him: Who brought thee hither? what dost thou here? why wouldst thou come hither?"}),"\n",(0,h.jsx)(n,{verse:4,children:"He answered them: Michas hath done such and such things for me, and hath hired me to be his priest."}),"\n",(0,h.jsx)(n,{verse:5,children:"Then they desired him to consult the Lord, that they might know whether their journey should be prosperous, and the thing should have effect."}),"\n",(0,h.jsx)(n,{verse:6,children:"He answered them: Go in peace: the Lord looketh on your way, and the journey that you go."}),"\n",(0,h.jsx)(n,{verse:7,children:"So the five men going on came to Lais: and they saw how the people dwelt therein without any fear, according to the custom of the Sidonians, secure and easy, having no man at all to oppose them, being very rich, and living separated, at a distance from Sidon and from all men."}),"\n",(0,h.jsx)(n,{verse:8,children:"And they returned to their brethren in Saraa and Esthaol, who asked them what they had done: to whom they answered:"}),"\n",(0,h.jsx)(n,{verse:9,children:"Arise, and let us go up to them: for we have seen the land which is exceeding rich and fruitful: neglect not, lose no time: let us go and possess it, there will be no difficulty."}),"\n",(0,h.jsx)(n,{verse:10,children:"We shall come to a people that is secure, into a spacious country, and the Lord will deliver the place to us, in which there is no want of any thing that groweth on the earth."}),"\n",(0,h.jsx)(n,{verse:11,children:"There went therefore of the kindred of Dan, to wit, from Saraa and Esthaol, six hundred men, furnished with arms for war."}),"\n",(0,h.jsx)(n,{verse:12,children:"And going up they lodged in Cariathiarim of Juda: which place from that time is called the camp of Dan, and is behind Cariathiarim."}),"\n",(0,h.jsx)(n,{verse:13,children:"From thence they passed into mount Ephraim. And when they were come to the house of Michas,"}),"\n",(0,h.jsx)(n,{verse:14,children:"The five men, that before had been sent to view the land of Lais, said to the rest of their brethren: You know that in these houses there is an ephod and theraphim, and a graven and a molten god: see what you are pleased to do."}),"\n",(0,h.jsx)(n,{verse:15,children:"And when they had turned a little aside, they went into the house of the young man the Levite, who was in the house of Michas: and they saluted him with words of peace."}),"\n",(0,h.jsx)(n,{verse:16,children:"And the six hundred men stood before the door, appointed with their arms."}),"\n",(0,h.jsx)(n,{verse:17,children:"But they that were gone into the house of the young man, went about to take away the graven god, and the ephod, and the theraphim, and the molten god, and the priest stood before the door, the six hundred valiant men waiting not far off."}),"\n",(0,h.jsx)(n,{verse:18,children:"So they that were gone in took away the graven thing, the ephod, and the idols, and the molten god, And the priest said to them: What are you doing?"}),"\n",(0,h.jsx)(n,{verse:19,children:"And they said to him: Hold thy peace, and put thy finger on thy mouth, and come with us, that we may have thee for a father, and a priest. Whether is better for thee, to be a priest in the house of one man, or in a tribe and family in Israel?"}),"\n",(0,h.jsx)(n,{verse:20,children:"When he heard this, he agreed to their words, and took the ephod, and the idols, and the graven god, and departed with them."}),"\n",(0,h.jsx)(n,{verse:21,children:"And when they were going forward, and had put before them the children and the cattle, and all that was valuable,"}),"\n",(0,h.jsx)(n,{verse:22,children:"And were now at a distance from the house of Michas, the men that dwelt in the houses of Michas gathering together followed them,"}),"\n",(0,h.jsx)(n,{verse:23,children:"And began to shout out after them. They looked back, and said to Michas: What aileth thee? Why dost thou cry?"}),"\n",(0,h.jsx)(n,{verse:24,children:"And he answered: You have taken away my gods which I have made me, and the priest, and all that I have, and do you say: What aileth thee?"}),"\n",(0,h.jsx)(n,{verse:25,children:"And the children of Dan said to him: See thou say no more to us, lest men enraged come upon thee, and thou perish with all thy house."}),"\n",(0,h.jsx)(n,{verse:26,children:"And so they went on the journey they had begun. But Michas seeing that they were stronger than he, returned to his house."}),"\n",(0,h.jsx)(n,{verse:27,children:"And the six hundred men took the priest, and the things we spoke of before, and came to Lais, to a people that was quiet and secure, and smote them with the edge of the sword: and the city they burnt with fire,"}),"\n",(0,h.jsx)(n,{verse:28,children:"There being no man at all who brought them any succour, because they dwelt far from Sidon, and had no society or business with any man. And the city was in the land of Rohob: and they rebuilt it, and dwelt therein,"}),"\n",(0,h.jsx)(n,{verse:29,children:"Calling the name of the city Dan, after the name of their father, who was the son of Israel, which before was called Lais."}),"\n",(0,h.jsx)(n,{verse:30,children:"And they set up to themselves the graven idol, and Jonathan the son of Gersam, the son of Moses, he and his sons were priests in the tribe of Dan, until the day of their captivity."}),"\n",(0,h.jsx)(n,{verse:31,children:"And the idol of Michas remained with them all the time that the house of God was in Silo. In those days there was no king in Israel."})]})}function c(e={}){const{wrapper:t}={...(0,o.R)(),...e.components};return t?(0,h.jsx)(t,{...e,children:(0,h.jsx)(l,{...e})}):l(e)}},71184:(e,t,n)=>{n.d(t,{R:()=>s,x:()=>i});var h=n(14041);const o={},a=h.createContext(o);function s(e){const t=h.useContext(a);return h.useMemo((function(){return"function"==typeof e?e(t):{...t,...e}}),[t,e])}function i(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(o):e.components||o:s(e.components),h.createElement(a.Provider,{value:t},e.children)}}}]);